def parse_json(s: str) -> object:
    """
    A state machine-based parser that reads the JSON string character by character to construct Python objects.
    It processes strings, numbers, booleans, null, arrays, and objects while maintaining a consistent state.
    """

    position = 0

    def next_token():
        nonlocal position
        while position < len(s) and s[position].isspace():
            position += 1
        if position == len(s):
            return None

        char = s[position]
        if char in '{[]},:':
            position += 1
            return char
        if char == '"':
            return read_string()
        if char == 't':
            return read_true()
        if char == 'f':
            return read_false()
        if char == 'n':
            return read_null()
        if char.isdigit() or char == '-':
            return read_number()
        return None

    def read_string():
        nonlocal position
        position += 1  # Skip opening quote
        start = position
        while position < len(s):
            if s[position] == '"':
                result = s[start:position].encode().decode('unicode_escape')
                position += 1  # Skip closing quote
                return result
            elif s[position] == '\\':
                position += 2  # Skip escape character
            else:
                position += 1
        raise ValueError("Unterminated string")

    def read_number():
        nonlocal position
        start = position
        if s[position] == '-':
            position += 1
        while position < len(s) and s[position].isdigit():
            position += 1
        if position < len(s) and s[position] == '.':
            position += 1
            while position < len(s) and s[position].isdigit():
                position += 1
        return float(s[start:position]) if '.' in s[start:position] else int(s[start:position])

    def read_true():
        nonlocal position
        if s.startswith('true', position):
            position += 4
            return True
        raise ValueError("Invalid value for true")

    def read_false():
        nonlocal position
        if s.startswith('false', position):
            position += 5
            return False
        raise ValueError("Invalid value for false")

    def read_null():
        nonlocal position
        if s.startswith('null', position):
            position += 4
            return None
        raise ValueError("Invalid value for null")

    def read_array():
        arr = []
        token = next_token()
        if token == ']':
            return arr
        position -= 1  # Go back to read the value
        while True:
            arr.append(parse_value())
            token = next_token()
            if token == ']':
                break
            if token != ',':
                raise ValueError("Expected ',' or ']' in array")
        return arr

    def read_object():
        obj = {}
        token = next_token()
        if token == '}':
            return obj
        position -= 1  # Go back to read the key
        while True:
            key = read_string()
            token = next_token()
            if token != ':':
                raise ValueError("Expected ':' after key in object")
            value = parse_value()
            obj[key] = value
            token = next_token()
            if token == '}':
                break
            if token != ',':
                raise ValueError("Expected ',' or '}' in object")
        return obj

    def parse_value():
        token = next_token()
        if token is None:
            raise ValueError("Unexpected end of input")

        if token == '{':
            return read_object()
        elif token == '[':
            return read_array()
